package com.resumeanalyzer.service;
import com.resumeanalyzer.dto.*; import com.resumeanalyzer.entity.*; import com.resumeanalyzer.exception.ResourceNotFoundException; import com.resumeanalyzer.repository.*; import com.resumeanalyzer.security.CurrentUser; import lombok.RequiredArgsConstructor; import org.springframework.ai.chat.client.ChatClient; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class ChatService { private final ChatMessageRepository messages; private final ResumeRepository resumes; private final CurrentUser currentUser; private final ChatClient.Builder chatClientBuilder; @Transactional public ChatResponseDto chat(ChatRequestDto request){User user=currentUser.require();Resume resume=request.resumeId()==null?null:resumes.findByIdAndUserId(request.resumeId(),user.getId()).orElseThrow(()->new ResourceNotFoundException("Resume not found"));messages.save(ChatMessage.builder().user(user).resume(resume).sender(ChatMessage.Sender.USER).content(request.prompt()).build());String context=resume==null?"No resume was selected.":resume.getRawText();String answer=chatClientBuilder.build().prompt().system("You are a concise, practical resume coach. Use only the provided resume as factual candidate context. Never invent qualifications.").user(u->u.text("RESUME CONTEXT:\n{resume}\n\nUSER QUESTION:\n{question}").param("resume",context).param("question",request.prompt())).call().content();ChatMessage saved=messages.saveAndFlush(ChatMessage.builder().user(user).resume(resume).sender(ChatMessage.Sender.BOT).content(answer).build());return new ChatResponseDto(saved.getId(),saved.getContent(),saved.getTimestamp());} }
